from bisect import bisect_left

def minRemovalsMountain(nums):
    def ending_lengths(a):
        tails = []
        out = []
        for x in a:
            i = bisect_left(tails, x)
            if i == len(tails):
                tails.append(x)
            else:
                tails[i] = x
            out.append(i + 1)
        return out

    n = len(nums)
    inc = ending_lengths(nums)
    dec = ending_lengths(nums[::-1])[::-1]
    best = 0
    for p in range(n):
        if inc[p] >= 2 and dec[p] >= 2:
            best = max(best, inc[p] + dec[p] - 1)
    return n - best
